public int MaxSumOfKConsecutive(int[] nums, int k)
{
    int windowSum = 0;

    for (int i = 0; i < k; i++)
        windowSum += nums[i];

    int best = windowSum;

    for (int i = k; i < nums.Length; i++)
    {
        windowSum += nums[i];
        windowSum -= nums[i - k];
        best = Math.Max(best, windowSum);
    }

    return best;
}

